% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 43, p43-q36-a-construction"}
\begin{tikzpicture}[x=2.2cm,y=2.2cm,line cap=round,line join=round,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (O) at (0,0);
\coordinate (P) at (90:1);
\coordinate (Q) at (220:1);
\coordinate (R) at (320:1);
\coordinate (M) at ($(Q)!0.5!(R)$);
\draw[black,line width=0.8pt] (O) circle (1);
\draw[black,line width=0.8pt] (P)--(Q)--(R)--cycle;
\draw[black,dashed,line width=0.4pt] (Q)--(O)--(R);
\draw[black,line width=0.4pt] (P)--(M);
\draw[black,line width=0.4pt] ($(P)!0.5!(Q)!2pt!90:(Q)$)--($(P)!0.5!(Q)!2pt!-90:(Q)$);
\draw[black,line width=0.4pt] ($(P)!0.5!(R)!2pt!90:(R)$)--($(P)!0.5!(R)!2pt!-90:(R)$);
\coordinate (U) at ($(M)!2mm!(O)$);
\coordinate (V) at ($(M)!2mm!(R)$);
\draw[black,line width=0.4pt] (U)--($(U)+(V)-(M)$)--(V);
\pic[draw=none,angle radius=5mm,angle eccentricity=1,"$\theta$"] {angle=Q--O--M};
\pic[draw=none,angle radius=5mm,angle eccentricity=1,"$\theta$"] {angle=M--O--R};
\node[above] at (P) {$P$};
\node[below left] at (Q) {$Q$};
\node[below right] at (R) {$R$};
\node[above right] at (O) {$O$};
\node[below] at (M) {$M$};
\end{tikzpicture}
